BEGIN;

SET LOCAL standard_conforming_strings = on;

INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷一百十六", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/d5d9d3447be330d5f5331703b94bb9b504dea8b6/content/books/zizhi-tongjian/vol-293/year-0956/part-02/sources/library/jiuwudaishi-116-six-prefecture-negotiation/source.txt", "note": "《旧五代史》卷一百十六，段落 jiu-wudaishi-205deb4a7860-p002754；EPUB电子本，纸本及异文待核", "id": "787619d0-d793-5059-bbc5-c2dda4008f78"}, {"title": "资治通鉴·后周纪四", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/d5d9d3447be330d5f5331703b94bb9b504dea8b6/content/books/zizhi-tongjian/vol-293/year-0956/part-02/sources/library/tongjian-293-956-li-deming-changzhou/source.txt", "note": "《资治通鉴》后周纪四，段落 zizhi-tongjian-a63549944a71-p003476；电子底本待考，分段待核", "id": "51d79b3a-2b70-5518-b7e9-6bdf24603483"}, {"title": "新五代史·卷三十三", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/d5d9d3447be330d5f5331703b94bb9b504dea8b6/content/books/zizhi-tongjian/vol-293/year-0956/part-02/sources/library/xinwudaishi-33-huainan-peace-negotiation/source.txt", "note": "《新五代史》卷三十三，段落 xin-wudaishi-b08f244b9241-p001210；EPUB电子本，纸本及异文待核", "id": "78fced7e-8bd2-5354-9de9-73b0a8084ac4"}, {"title": "资治通鉴·后周纪四", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/716a3d9ea101493ffb96bbdc98041c65d71f2fd6/content/books/zizhi-tongjian/vol-293/year-0956/part-01/sources/library/tongjian-293-956-march-opening/source.txt", "note": "《资治通鉴》后周纪四，段落 zizhi-tongjian-a63549944a71-p003475；电子底本待考，分段待核", "id": "7aa67de9-08ee-52d7-b5ed-85e2e35a19bc"}, {"title": "旧五代史·卷一百十六", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/716a3d9ea101493ffb96bbdc98041c65d71f2fd6/content/books/zizhi-tongjian/vol-293/year-0956/part-01/sources/library/jiuwudaishi-116-march-956/source.txt", "note": "《旧五代史》卷一百十六，段落 jiu-wudaishi-205deb4a7860-p002748；EPUB电子本，纸本及异文待核", "id": "f1bed893-849b-56a4-8ac1-ca7e289e131e"}, {"title": "新五代史·卷六十七", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/5b7d39c10017d28c66750d6a92a9b6db748131ef/content/books/zizhi-tongjian/vol-292/year-0956/part-03/sources/library/xinwudaishi-67-chenman-misidentifies/source.txt", "note": "《新五代史》卷六十七，段落 xin-wudaishi-b08f244b9241-p003376；EPUB电子本，纸本及异文待核", "id": "af34714e-89b9-5742-afa9-288c8dcd6168"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "柴荣", "aliases": ["郭荣", "柴榮", "郭榮"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本姓柴，950年《资治通鉴》以郭荣记名，任贵州刺史、天雄牙内都指挥使。父亲柴守礼是郭威妻子柴氏的兄长，郭威在尚无儿子时收养他。《新五代史》记他幼年跟随姑母在郭威家成长。《旧五代史》的任职纪年与通鉴不同，分别保留。", "biography": null, "status": "draft", "id": "697c1a4f-b373-5a78-8b47-330fe349a424"}, {"name": "马希崇", "aliases": ["馬希崇"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "马希广的庶弟、马希萼的弟弟。947年任楚天策左司马，秘密致信马希萼指责继位安排，又向他报告马希广的言行并约为内应。生卒年尚未录入。", "biography": null, "status": "draft", "id": "7c876e99-eb52-5864-9569-0ede35f9ff7b"}, {"name": "王继沂", "aliases": ["王繼沂"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "王延政之子。956年三月与马希崇都在扬州，柴荣下诏抚慰存问。此段未载官职和生卒年。", "biography": null, "status": "draft", "id": "d7079cfc-aa6a-522f-b7a6-725156231400"}, {"name": "王延政", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：王延政，都教练使、赴建州抚慰者。", "biography": null, "status": "draft", "id": "83601670-f3dc-5559-b599-e39bda91eb6c"}, {"name": "孙晟", "aliases": ["孫晟", "孙凤", "孫鳳", "孙忌", "孫忌"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷276天成二年条所见人物：孙晟，判官、劝反者。", "biography": null, "status": "draft", "id": "38c30b43-89f4-5133-8970-38f2fb8f157e"}, {"name": "刘仁赡", "aliases": ["劉仁贍"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐将领，刘金之子，字守惠、彭城人。951年以武昌节度使身份率二百艘战舰攻取岳州。《新五代史》还记他早年任左监门卫将军、黄袁二州刺史，后掌亲军。生卒年尚未录入。", "biography": null, "status": "draft", "id": "fbdf8a53-b985-5dda-a5d1-e96cf9d7121c"}, {"name": "李璟", "aliases": ["徐景通", "景通", "李景"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：李璟。", "biography": null, "status": "draft", "id": "6bf72971-88c3-5187-8f25-98cde2a9554a"}, {"name": "李德明", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐尚书员外郎。949年条下与钟谟一起参与国政，史书记两人受李璟宠信，但不是魏岑的同党。生卒年尚未录入。", "biography": null, "status": "draft", "id": "3aa99691-05a6-5807-a0c3-f56c9cebb4f1"}, {"name": "王崇质", "aliases": ["王崇質"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐礼部尚书。956年三月奉李璟命与司空孙晟一起向后周奉表求和。生卒年未载。", "biography": null, "status": "draft", "id": "45e5f866-09d5-538f-b98c-ba31c3939853"}, {"name": "安弘道", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周供奉官。956年三月奉柴荣命护送李德明、王崇质回金陵，并携致李璟的诏书。生卒年未载。", "biography": null, "status": "draft", "id": "d3d9ff07-87c3-50eb-945d-c1b5d0a7e54e"}, {"name": "宋齐丘", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷268乾化二年条所见人物：宋齐丘。", "biography": null, "status": "draft", "id": "313ec6c3-7027-5fef-8b5d-b79d259f9c8a"}, {"name": "陈觉", "aliases": ["陳覺"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：陈觉，海陵人、参与谈议者。", "biography": null, "status": "draft", "id": "8f8c34eb-c238-596f-a688-8b8332b405a1"}, {"name": "李征古", "aliases": ["李徵古"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐枢密副使。《通鉴》记956年参与指控李德明卖国，后来在常州救援部署中给柴克宏朽损装备、召其回朝并拟用朱匡业替代。指控与能力评价保留来源立场，不认作李德明确实卖国。", "biography": null, "status": "draft", "id": "4166fee2-b566-55ec-8218-943eafdc5242"}, {"name": "吴程", "aliases": ["吳程"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "山阴人，吴越丞相。947年十二月鲍修让将李仁达首级送到钱塘后，钱弘倧任吴程主持威武节度事务。生卒年未载。", "biography": null, "status": "draft", "id": "70950e94-6804-5b3e-afb7-43c0ab271dea"}, {"name": "赵仁泽", "aliases": ["趙仁澤"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐常州团练使。956年被吴程俘获送到钱唐，因不向钱弘俶行拜礼并责其违约而受伤；元德昭为他敷药，得以活命。生卒年未载。", "biography": null, "status": "draft", "id": "78e72f6b-ce65-5093-bd51-1ed98d6f7f41"}, {"name": "钱弘俶", "aliases": ["钱俶", "錢俶", "錢弘俶"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "钱传瓘之子，母亲吴氏。《宋史》本传明确本名弘俶，后名钱俶；《资治通鉴》所用电子本在王室家属追述中把俶写作拆分字形。生卒年暂未录全。", "biography": null, "status": "draft", "id": "3a65648c-82a5-5d66-be49-1fbc1ccb4e70"}, {"name": "元德昭", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "危仔倡之子。946年吴越出兵救福州时，钱弘佐把军事谋划交给他。其姓名与父亲异姓按史书记载保留，不据此猜测改姓原因或收养关系；生卒年未载。", "biography": null, "status": "draft", "id": "3f40b6ff-27d0-5eae-a8f2-983b144f4081"}, {"name": "李弘冀", "aliases": ["弘冀", "李冀"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "李璟的长子。943年七月条下被立为南昌王。姓名在《资治通鉴》作弘冀，《新五代史》同一册封作冀；沿用同一主体，不因姓名省写再建李冀。生卒年尚未核。", "biography": null, "status": "draft", "id": "e4027731-d3e9-5cd1-8c58-d504f38025da"}, {"name": "赵铎", "aliases": ["趙鐸"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐燕王李弘冀的部将。956年吴越军攻常州时，劝李弘冀不要离开军府回金陵，以免动摇军心。生卒年未载。", "biography": null, "status": "draft", "id": "9d8098b9-f4a6-5f80-92de-486ab1e7536f"}, {"name": "柴克宏", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐龙武都虞候，柴再用之子。956年请求出战，其母亦上表荐子，李璟任其为右武卫将军赴常州救援。虽然装备劣、被召还，仍进军，在常州击败吴越军。生卒年待后续段落。", "biography": null, "status": "draft", "id": "e35c0e24-ccd9-5b3b-8e02-7e842ac1aeb8"}, {"name": "柴再用", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷260乾宁二年条所见人物：柴再用。", "biography": null, "status": "draft", "id": "4e688db5-7a48-5fbc-a4b3-45d22d254217"}, {"name": "柴克宏母（姓名未载）", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "史书未记姓名。956年柴克宏请求出战时，上表称儿子有父亲遗风、可为将，并愿承担举荐不当的责任。用亲属称谓识别此位确有行动的人物，不编造姓名、生卒年或其他身世。", "biography": null, "status": "draft", "id": "39ed54c9-26c6-5450-9755-51a378076d78"}, {"name": "陆孟俊（南唐袁州刺史）", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐袁州刺史。956年获命与柴克宏会兵救常州。与951年楚牙内侍卫指挥使陆孟俊暂无完整连续履历证据，暂分档保存，后续再核是否同人。", "biography": null, "status": "draft", "id": "dee3002f-1b01-51ab-9084-b906a16115b3"}, {"name": "朱匡业", "aliases": ["硃匡業", "朱匡業"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐神卫统军。956年李征古拟让其代柴克宏，随后到达常州行营，柴克宏谨慎事奉。史书字形硃沿原文，主体用朱；生卒年未载。", "biography": null, "status": "draft", "id": "8300b93a-97ee-584f-b7f5-990378a6c507"}, {"name": "乔匡舜", "aliases": ["喬匡舜"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐中书舍人。956年赴吴越出使，柴克宏进常州时声称船队是迎接他，以掩护登岸突袭。生卒年未载。", "biography": null, "status": "draft", "id": "9c534c02-4acf-5688-8211-5c3577943c94"}, {"name": "罗晟", "aliases": ["羅晟"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "吴越中直都指挥使。956年二月钱弘俶派吴程督鲍修让、罗晟赴常州。生卒年未载。", "biography": null, "status": "draft", "id": "19e44dec-b085-579c-821d-0087cde81018"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "柴荣下诏抚慰在扬州的马希崇和王继沂", "start_year": 956, "end_year": 956, "time_original": "956年三月条所记，具体诏日未载", "dynasty": "五代十国", "description": "柴荣下诏抚慰在扬州的马希崇和王继沂。", "phases": [], "location_name": "扬州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "ae57d78e-2ead-5c82-b129-595f58e2fc6a"}, {"title": "孙晟等抵达柴荣行在", "start_year": 956, "end_year": 956, "time_original": "956年三月丙午", "dynasty": "五代十国", "description": "孙晟等抵达柴荣行在。", "phases": [], "location_name": "后周行在", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "e6e21de6-65c6-56b4-b36b-00b44822a497"}, {"title": "柴荣派中使带孙晟到寿春城下招谕刘仁赡", "start_year": 956, "end_year": 956, "time_original": "956年三月庚戌", "dynasty": "五代十国", "description": "柴荣派中使带孙晟到寿春城下招谕刘仁赡。", "phases": [], "location_name": "寿春城下", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "1874f055-f2c8-52cc-9d2c-f176d0948fde"}, {"title": "刘仁赡在城上行礼，孙晟劝他守住对南唐的忠诚", "start_year": 956, "end_year": 956, "time_original": "956年三月庚戌招谕时", "dynasty": "五代十国", "description": "刘仁赡在城上行礼，孙晟劝他守住对南唐的忠诚。", "phases": [], "location_name": "寿春城上与城下", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "9ae40e0b-e8c9-5cf7-9cf3-1bc9b74427f1"}, {"title": "柴荣因孙晟劝守而生气，孙晟申明职责后获释", "start_year": 956, "end_year": 956, "time_original": "956年三月庚戌城下对话之后，具体处置日未另列", "dynasty": "