{"title": "柴克宏所领兵老弱，李征古又给朽损装备，柴请求后遭斥骂", "start_year": 956, "end_year": 956, "time_original": "956年三月赴常州前", "dynasty": "五代十国", "description": "《通鉴》称南唐精兵在江北，柴克宏领的数千人老弱，李征古又给朽损装备。柴提出意见遭斥骂，部众愤怒而柴保持平静。这是当时处境及史书评判，不推导未载装备损坏比例或军费数额。", "phases": [], "location_name": "南唐军队", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "d656d410-af2c-57ae-8817-d58c6d64555b"}, {"title": "李征古在柴克宏至润州时召其回朝，拟用朱匡业替代", "start_year": 956, "end_year": 956, "time_original": "956年三月常州救援行军中", "dynasty": "五代十国", "description": "李征古在柴克宏至润州时召其回朝，拟用朱匡业替代。", "phases": [], "location_name": "润州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "8bdf11fb-944f-5c42-8efd-18d6492d6805"}, {"title": "李弘冀支持柴克宏继续作战，并上表反对中途换将", "start_year": 956, "end_year": 956, "time_original": "956年三月润州救援部署时", "dynasty": "五代十国", "description": "李弘冀支持柴克宏继续作战，并上表反对中途换将。", "phases": [], "location_name": "润州至南唐朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "86a5e96b-0a58-5608-a5e1-a3c0f9c1755a"}, {"title": "柴克宏进军常州，面对再次召还，命处死使者", "start_year": 956, "end_year": 956, "time_original": "956年三月继续进军常州时", "dynasty": "五代十国", "description": "柴克宏继续赶往常州，李征古再次遣使召他回去。柴声称使者必是奸人，命将其斩杀；使者申明受枢密命令，柴仍说李征古亲来也会斩。奸人是柴的判断，不据此确认使者身份造假，也不写成柴已杀李征古。", "phases": [], "location_name": "赴常州途中", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "e2b0aa4b-cc81-5bfa-9cd6-20fbe459e72f"}, {"title": "李璟先派乔匡舜出使吴越", "start_year": null, "end_year": null, "time_original": "956年三月柴克宏突袭常州之前，具体使行年日未载", "dynasty": "五代十国", "description": "李璟先派乔匡舜出使吴越。", "phases": [], "location_nam